-- 0102-npc-skills.sql — Canonical special skills, combat techniques, and arts for all NPCs.

CREATE TABLE IF NOT EXISTS np_skill (
    id             INTEGER PRIMARY KEY AUTOINCREMENT,
    npc_id         INTEGER NOT NULL REFERENCES np_npc(id),
    code           TEXT    NOT NULL,
    name_vi        TEXT    NOT NULL,
    category       TEXT    NOT NULL CHECK (category IN ('martial', 'strategist', 'governance', 'commerce', 'special')),
    tier           INTEGER NOT NULL DEFAULT 1 CHECK (tier BETWEEN 1 AND 5),
    description    TEXT    NOT NULL,
    effect_summary TEXT    NOT NULL,
    UNIQUE(npc_id, code)
);

CREATE INDEX IF NOT EXISTS ix_np_skill_npc ON np_skill(npc_id);

